create extension if not exists "uuid-ossp";
create table categories(id uuid primary key default uuid_generate_v4(),name text not null unique,description text,image_url text,created_at timestamptz default now());
create table users(id uuid primary key default uuid_generate_v4(),name text not null,email text not null unique,phone text,password text not null,role text not null default 'user' check(role in ('user','admin')),created_at timestamptz default now(),updated_at timestamptz default now());
create table products(id uuid primary key default uuid_generate_v4(),name text not null,description text,price numeric(12,2) not null check(price>=0),original_price numeric(12,2),discount integer default 0,category_id uuid references categories(id) on delete set null,gender text,brand text,stock integer default 0 check(stock>=0),sizes jsonb default '[]',colors jsonb default '[]',image_url text,rating numeric(2,1) default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table cart(id uuid primary key default uuid_generate_v4(),user_id uuid not null references users(id) on delete cascade,product_id uuid not null references products(id) on delete cascade,quantity integer not null check(quantity>0),created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id,product_id));
create table wishlist(id uuid primary key default uuid_generate_v4(),user_id uuid not null references users(id) on delete cascade,product_id uuid not null references products(id) on delete cascade,created_at timestamptz default now(),unique(user_id,product_id));
create table addresses(id uuid primary key default uuid_generate_v4(),user_id uuid not null references users(id) on delete cascade,name text,phone text,address_line text,city text,state text,pincode text,country text default 'India',created_at timestamptz default now());
create table orders(id uuid primary key default uuid_generate_v4(),user_id uuid not null references users(id),total_amount numeric(12,2) not null,status text default 'Processing',payment_status text default 'Pending',payment_method text,shipping_address jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table order_items(id uuid primary key default uuid_generate_v4(),order_id uuid not null references orders(id) on delete cascade,product_id uuid references products(id),quantity integer not null,price numeric(12,2) not null,created_at timestamptz default now());
create table payments(id uuid primary key default uuid_generate_v4(),order_id uuid not null references orders(id) on delete cascade,user_id uuid not null references users(id),payment_method text,transaction_id text,amount numeric(12,2),status text,created_at timestamptz default now());
create table reviews(id uuid primary key default uuid_generate_v4(),user_id uuid references users(id) on delete cascade,product_id uuid references products(id) on delete cascade,rating integer check(rating between 1 and 5),comment text,created_at timestamptz default now());
create table coupons(id uuid primary key default uuid_generate_v4(),code text unique not null,discount_type text,discount_value numeric,minimum_amount numeric,expires_at timestamptz,created_at timestamptz default now());
create index products_search_idx on products(gender,category_id,price);create index cart_user_idx on cart(user_id);create index orders_user_idx on orders(user_id);
